insert into attendances (
  club_id, activity_id, member_id, attendance_type, attendance_time, remark,
  exception_flag, exception_status, exception_reason
) values (
  #{clubId}, #{activityId}, #{memberId}, #{attendanceType}, #{attendanceTime}, #{remark},
  ifnull(#{exceptionFlag}, 0), ifnull(#{exceptionStatus}, 0), #{exceptionReason}
)

mapper.select:
select

from attendances

  
    and club_id = #{clubId}
  
  
    and activity_id = #{activityId}
  
  
    and member_id = #{memberId}
  
  
    and attendance_time >= #{startTime}
  
  
    and attendance_time <= #{endTime}
  

order by attendance_time desc

select
  null as ref_id,
  'summary' as ref_name,
  count(1) as total_count,
  sum(case when attendance_type = 1 then 1 else 0 end) as normal_count,
  sum(case when attendance_type = 2 then 1 else 0 end) as late_count,
  sum(case when attendance_type = 3 then 1 else 0 end) as leave_early_count,
  sum(case when attendance_type = 4 then 1 else 0 end) as absent_count,
  sum(case when exception_flag = 1 then 1 else 0 end) as exception_count
from attendances

  
    and club_id = #{clubId}
  
  
    and activity_id = #{activityId}
  
  
    and member_id = #{memberId}
  
  
    and attendance_time >= #{startTime}
  
  
    and attendance_time <= #{endTime}

select a.member_id as ref_id, coalesce(u.username, concat('member-', a.member_id)) as ref_name, count(1) as total_count, sum(case when a.attendance_type = 1 then 1 else 0 end) as normal_count, sum(case when a.attendance_type = 2 then 1 else 0 end) as late_count, sum(case when a.attendance_type = 3 then 1 else 0 end) as leave_early_count, sum(case when a.attendance_type = 4 then 1 else 0 end) as absent_count, sum(case when a.exception_flag = 1 then 1 else 0 end) as exception_count from attendances a join members m on a.member_id = m.id left join users u on m.user_id = u.id where a.club_id = #{clubId}
and a.attendance_time >= #{startTime}
and a.attendance_time <= #{endTime}
group by a.member_id, u.username order by total_count desc limit 50

select a.activity_id as ref_id, coalesce( act.activity_name, case when a.activity_id is null then '日常考勤' else concat('活动-', a.activity_id) end ) as ref_name, count(1) as total_count, sum(case when a.attendance_type = 1 then 1 else 0 end) as normal_count, sum(case when a.attendance_type = 2 then 1 else 0 end) as late_count, sum(case when a.attendance_type = 3 then 1 else 0 end) as leave_early_count, sum(case when a.attendance_type = 4 then 1 else 0 end) as absent_count, sum(case when a.exception_flag = 1 then 1 else 0 end) as exception_count from attendances a left join activities act on a.activity_id = act.id where a.club_id = #{clubId}
and a.attendance_time >= #{startTime}
and a.attendance_time <= #{endTime}
group by a.activity_id, act.activity_name order by total_count desc limit 50

select null as ref_id, date_format(a.attendance_time, '%Y-%m-%d') as ref_name, count(1) as total_count, sum(case when a.attendance_type = 1 then 1 else 0 end) as normal_count, sum(case when a.attendance_type = 2 then 1 else 0 end) as late_count, sum(case when a.attendance_type = 3 then 1 else 0 end) as leave_early_count, sum(case when a.attendance_type = 4 then 1 else 0 end) as absent_count, sum(case when a.exception_flag = 1 then 1 else 0 end) as exception_count from attendances a where a.club_id = #{clubId}
and a.attendance_time >= #{startTime}
and a.attendance_time <= #{endTime}
group by date_format(a.attendance_time, '%Y-%m-%d') order by ref_name desc limit 30

mapper.update:
update attendances
set exception_flag = 1,
    exception_status = 0,
    exception_reason = #{reason}
where id = #{id}
